-- ============================================================================
-- 적정성평가 Q&A — 병원 실무 카톡 질의응답 추출분 (2026-08-05)
--   · 원천 : 일반병원(원무과장) ↔ 위너넷 컨설팅 카카오톡 대화(2025-12-29 ~ 2026-08-05)
--            에서 <업무 질문 + 위너넷 답변>을 추출·일반화. 병원명·환자명은 제거함.
--   · 제외 : 점수 관리 요령성 답변(개선율 계획 %, 평가표 상태 변경 문구 등)은
--            공개 지식으로 부적절하여 넣지 않음. 특정 환자 케이스 판정도 제외.
--   · 분류 : 평가표 작성 → IN_PAT / 지표 산정 → IN_IND / 수가·청구 실무 → IN_FEE(신규)
--   · HIT_CNT : 대화에서 실제로 물어본 횟수를 씨앗값으로 넣음(가짜 조회수 아님).
--   · 실행 : 운영 DB(WNN)에 이 파일 전체 실행. 화면 배포 불필요(재조회로 반영).
--            재실행 대비 KB 는 KB_CODE UNIQUE — 중복 실행 시 오류가 나면 이미 들어간 것.
-- ============================================================================

-- ── 신규 카테고리 : 수가·청구 실무 ──────────────────────────────────────────
SELECT 'IN_FEE',NULL,'수가·청구 실무(질의)','병원 문의에서 정리한 행위수가·삭감·청구 실무 답변','IN',6
WHERE NOT EXISTS (SELECT 1 FROM TBL_QNA_CAT WHERE CAT_ID='IN_FEE');

-- ══ 환자평가표 작성 (IN_PAT) ════════════════════════════════════════════════


-- ══ 지표·평가기준 (IN_IND) ══════════════════════════════════════════════════


-- ══ 수가·청구 실무 (IN_FEE — 신규 카테고리) ═════════════════════════════════


-- 확인용
SELECT CAT_ID, COUNT(*) FROM TBL_QNA_KB WHERE KB_CODE LIKE 'ask-%' GROUP BY CAT_ID;
