INSERT INTO TBL_QNA_CAT (CAT_ID,P_CAT_ID,CAT_NM,CAT_DESC,SRC_TYPE,SORT_NO)
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,HIT_CNT,SORT_NO) VALUES
('ask-pat-prev-apply','IN_PAT',NULL,'IN','CARD','당월에 적용할 평가표가 없으면(관찰기간 부족) 어떻게 하나요?','당월 적용할 평가표가 없으면 어떻게 하나요','이전평가표 이전적용 특정기간종료 관찰기간부족 단축작성 평가표없음 사망 6일','특정기간 종료 후 남은 기간이 짧아(예: 6일) 당월 평가표를 온전히 작성할 수 없는 경우, <b>최근 3개월 이내의 가장 최근 환자평가표를 이전 적용</b>하실 수 있습니다.\n관찰기간을 <b>단축해 작성</b>하는 방법도 가능합니다 — 두 방법 모두 인정되며, 병원에 유리한 평가표를 선택해 적용하셔도 됩니다.\n특정기간이 월중에 종료되고 <b>월말까지 관찰기간 7일이 확보</b>되는 경우에는, 특정기간 종료 후 작성한 평가표를 앞 기간(입원 초 며칠)에도 적용할 수 있습니다.\n다만 뒤에 작성하는 방식은 유치도뇨관 관찰기간이 길어지는 점을 함께 고려하셔야 합니다.',NULL,'ask-ind-prev-notrain','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,1),
('ask-pat-cancer-pain','IN_PAT',NULL,'IN','CARD','암성통증·통증관련치료는 어떤 경우에 체크할 수 있나요?','암성통증·통증치료는 어떤 경우에 체크하나요','암성통증 통증관련치료 마약성진통제 패취 패치 골절통증 타진 옥시코돈 진통제','<b>암환자</b>: 마약성 진통제(타진·옥시코돈 등)로 통증 조절 중이면 경구·패취 모두 인정될 수 있습니다. 다만 <b>의무기록에 통증의 강도·투여 빈도·환자상태</b>가 기록되어야 하며, 단순 진통제만 쓰는 경우는 불인정입니다.\n<b>암환자가 아닌 경우</b>(골절 등): <b>주사제로 통증 치료한 경우에만</b> 인정됩니다. 패취 부착은 통증관련치료 ''예''로 체크할 수 없습니다.\n골절로 인한 통증은 <b>3개월까지만</b> 통증으로 인정됩니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,2),
('ask-pat-op-wound','IN_PAT',NULL,'IN','CARD','수술창상·수술창상치료는 언제까지 체크할 수 있나요?','수술창상은 언제까지 체크할 수 있나요','수술창상 수술창상치료 stitch out 봉합사제거 경피적척추성형술 PCD 배액관','수술 후 <b>stitch out(봉합사 제거) 전까지</b> 수술창상·수술창상치료 체크가 가능합니다(욕창 사진처럼 근거 사진 첨부 권장).\nPCD 등 배액관 부위는 <b>3개월까지</b> 산정 가능합니다. 염증 상태가 동반되면 염증성 처치, <b>염증 없이 배액만 관찰되면 단순처치</b>로 산정합니다.\n수술 부위에 다른 피부문제(예: 당뇨발)가 함께 있으면 두 항목 모두 체크할 수 있습니다 — 실제 상태가 각각 해당된다면 중복 체크가 가능합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,3),
('ask-pat-sore-hist','IN_PAT',NULL,'IN','CARD','욕창 개수가 줄어든 경우에도 욕창 과거력 ''있음''인가요?','욕창 개수가 줄면 과거력 있음인가요','욕창과거력 지난1년 욕창력 치유 힐링 개수감소 과거력있음','네. <b>치유된 욕창이 하나라도 있으면 ''지난 1년 사이의 욕창 과거력 있음''</b>으로 체크합니다.\n예) 욕창 3개 중 1개 치유·2개 잔존 → 과거력 <b>있음</b> / 욕창 2개 중 1개 치유·1개 잔존 → 과거력 <b>있음</b>\n현재 남아 있는 욕창은 <b>현존 욕창</b>으로 평가하고, 치유된 욕창만 과거력으로 별도 반영합니다.\n(과거력 항목은 압박성 궤양 기준이며, 울혈성·허혈성·말초신경병증 궤양은 해당하지 않습니다.)',NULL,'ask-ind-sore-count','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,4),
('ask-pat-sore-grade1','IN_PAT',NULL,'IN','CARD','1단계 욕창도 평가표 처치·개선에 들어가나요?','1단계 욕창도 처치·개선에 들어가나요','1단계욕창 G1 단순처치 드레싱해제 욕창1단계 발적','<b>1단계 욕창의 단순처치는 평가표에 체크할 수 없습니다.</b>\n심사평가원은 1단계를 <b>욕창 개선 대상자로 간주하지 않으므로</b> 개선 분모에도 포함되지 않고, <b>욕창처치 실시 환자분율에만</b> 들어갑니다.\n1단계만 남은 상태라면 평가표의 ''피부궤양 드레싱'' 체크는 해제해야 합니다.',NULL,'ask-ind-sore-denom','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,5),
('ask-pat-parkinson','IN_PAT',NULL,'IN','CARD','파킨슨 질병진단은 산정특례가 없어도 체크할 수 있나요?','파킨슨은 산정특례 없어도 체크 가능한가요','파킨슨 산정특례 산특 G20 질병진단 소견서 진단명','산정특례가 있는 환자만 체크할 수 있는 것은 <b>아닙니다</b>. 입원 시 <b>소견서(또는 처방전)에 파킨슨 진단이 있고 약물 투여 중</b>이면 산특이 없어도 인정됩니다.\n다만 <b>소견서에 진단명 없이 약만 복용 중</b>인 경우에는 인정받기 어렵습니다. 타병원 진단서·처방기록으로 재심을 진행해도 <b>환자 상태 기록이 없으면 불인정</b>된 사례가 있습니다.\n<b>본원에서 증상만으로 진단 후 투약한 경우는 인정되지 않는 것이 원칙</b>입니다. 심사자 재량으로 넘어가더라도 추후 자료요청·문제 소지가 있으니, 급성기병원 검사·진단을 받아오도록 안내하고 거절 시 체크를 빼는 것이 안전합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,6),
('ask-pat-coma','IN_PAT',NULL,'IN','CARD','혼수(최고도) 체크에는 어떤 기록이 필요한가요?','혼수 체크에는 어떤 기록이 필요한가요','혼수 최고도 GCS 글래스고 혼수검사 stupor 의식저하 사망임박','의사 의무기록에 혼수상태라고 적는 것만으로는 부족하며, <b>GCS(글래스고 혼수척도) 검사 결과지</b>를 작성해 두셔야 합니다. 심사평가원에서 혼수검사 결과지 제출을 요구합니다.\nT-tube 등으로 말을 못하는 환자의 언어반응 평가는 별도 기준을 참고해 담당의가 작성합니다.\n다만 <b>사망 임박 시기의 의식저하</b>(다장기 부전)를 혼수로 체크하는 것은 의사 판단이더라도 심사평가원 인정 여부가 명확하지 않으니 신중해야 합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,7),
('ask-pat-urine-level','IN_PAT',NULL,'IN','CARD','소변조절상태(가끔·자주 실금, 조절 못함)는 어떤 기준으로 판정하나요?','소변조절상태는 어떤 기준으로 판정하나요','소변조절 가끔실금 자주실금 조절못함 실금횟수 배설기능 판정기준 기록예문','평가표 작성일 하루가 아니라 <b>관찰기간 동안의 배설 상태를 종합</b>해 평가합니다. 하루 24시간 기준 <b>조절 횟수와 실금 횟수를 비교</b>하여:\n· 조절 ≥ 실금 → <b>1. 가끔 실금함</b>\n· 실금 > 조절 → <b>2. 자주 실금함</b>\n· 배뇨 시마다 실금 → <b>3. 조절 못함</b>\n의무기록에 매일 소변·실금 횟수를 반드시 기록해야 하는 것은 아니지만, ''간헐적 실금 관찰됨''만 반복되면 판단 근거가 부족할 수 있습니다.\n권장 기록 예) ''요의 표현 가능하며 대부분 소변 조절 가능하나 간헐적 실금 관찰됨'' / ''소변 5회 중 1~2회 실금 관찰됨'' / ''반복적인 소변 실금으로 배뇨 조절 어려움'' — 조절 상태와 실금 상태를 함께 확인할 수 있게 작성합니다.',NULL,'ask-pat-udiary-content','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,8),
('ask-pat-udiary-3d','IN_PAT',NULL,'IN','CARD','배뇨일지를 3일만 작성했으면 평가표에 어떻게 체크하나요?','배뇨일지 3일 작성 시 평가표 체크는','배뇨일지 3일 7일 아니오 작성일수 개정고시 배뇨일지작성여부','개정 고시 이후 <b>배뇨일지를 7일 미만 작성한 경우 ''아니오''를 체크하고 실제 작성일수를 기재</b>합니다. 7일을 모두 작성한 경우에만 기존처럼 ''예''를 체크합니다.\n의료중도 산정을 위한 배뇨일지가 아니라면 <b>연속 3일 이상</b>이면 충분합니다.\n배뇨일지를 작성했더라도 <b>배뇨훈련 항목(일정하게 짜여진 배뇨계획·방광훈련프로그램)이 미체크</b>면 분자에서 누락되므로, 실제 시행한 방식에 맞게 반드시 체크하세요.',NULL,'ask-pat-utrain-rec','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,9),
('ask-pat-udiary-content','IN_PAT',NULL,'IN','CARD','배뇨일지에는 무엇을 기록해야 하나요? V표시만 해도 되나요?','배뇨일지에는 무엇을 기록해야 하나요','배뇨일지 배뇨량 확인표시 V표시 실금여부 배뇨횟수 기저귀','배뇨일지에는 <b>실시일자 · 실금 여부 · 배뇨횟수(또는 배뇨량 mL)</b>를 반드시 포함해야 합니다.\n확인란에 <b>''V'' 표시만 하면 배뇨횟수·배뇨량을 확인할 수 없어 기록 보완 요구</b>가 나옵니다. 실금이 있으면 실금량(mL)까지 확인되도록 작성하는 것이 원칙입니다.\n배뇨여부를 유/무로 체크하는 양식이라면 하단에 배뇨훈련 성공횟수와 배뇨량을 함께 작성해 관리하고, 배뇨일지 수정이 어렵다면 해당일 배뇨훈련 진행사항을 <b>간호기록으로 보완</b>합니다.',NULL,'ask-pat-udiary-3d,ask-pat-urine-level','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,10),
('ask-pat-utrain-rec','IN_PAT',NULL,'IN','CARD','배뇨훈련은 언제부터 어떻게 기록해야 인정되나요?','배뇨훈련 기록은 어떻게 해야 인정되나요','배뇨훈련 배뇨관리 기록 의사지시 시간간격 종결기록 평가기간','<b>의사 지시</b>에 훈련 방법과 <b>시간 간격(예: 3시간 간격)</b>을 명시하고, 간호기록·배뇨일지가 그 간격과 <b>시간이 일치</b>해야 합니다. ''일정하게 짜여진 배뇨계획''은 정해진 시간에 맞춰 배뇨를 유도하는 것이므로, 계획 시간 외 배뇨는 실금으로 기록합니다.\n기록 요령: 시작 시 어떤 방법으로 시행하는지 간호기록 → 훈련 기간 중 <b>1일 1회 이상</b> 훈련 중 기록 → 종료 시 <b>종결 기록</b>.\n배뇨관리는 <b>평가기간에만 시행해도 인정</b>되며, 평가표 작성일 3일 전부터 시행해도 됩니다. 월초 퇴원 등으로 3일 확보가 어려우면 <b>전월 말일부터 기록을 남기고 시행</b>합니다(퇴원일 포함 3일 인정).',NULL,'ask-pat-udiary-3d,ask-pat-udiary-content','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,11),
('ask-pat-quetiapine','IN_PAT',NULL,'IN','CARD','쿠에티아핀(큐로켈) 처방 시 상병은 무엇으로 넣어야 하나요?','큐로켈 처방 시 상병은 무엇으로','큐로켈 쿠에티아핀 수면장애 우울증 조현병 F32 상병 정신질환','큐로켈은 정신행동 관련 약물이라 <b>수면장애 상병으로는 불가</b>합니다 — 수면장애에는 수면제가 들어가야 합니다. <b>우울증(F32 등) 상병</b>을 사용합니다.\n요양병원 입원 대상에서 정신질환자가 제외되는 것과 관련해서는, <b>조현병이 주상병인 환자가 아니면</b> 부상병으로 사용해도 문제되지 않습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,12);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,HIT_CNT,SORT_NO) VALUES
('ask-ind-sore-denom','IN_IND',NULL,'IN','CARD','욕창 개선 분모·제외 대상은 어떻게 되나요? (악화가 있으면?)','욕창 개선 분모·제외 대상은','욕창개선 분모 제외대상 악화 개선악화동시 전월평가표없음 특정기간','<b>전월 2단계 이상 욕창이 있는 환자</b>가 당월 개선 분모입니다.\n<b>악화만 있는 환자는 분모에 포함</b>되고(개선 0), 한 환자에게 <b>개선과 악화가 동시에</b> 발생한 경우에만 제외됩니다.\n전월에 평가표가 없으면(특정기간 등) <b>분모에 포함되지 않습니다</b> — 이 경우 당월 평가표 작성 이후에 개선되는 것이 지표에 반영됩니다.\n전월 욕창 3개(G2) 환자를 3개월에 걸쳐 1개씩 치유하면 <b>매월 개선 환자로 반영</b>됩니다.',NULL,'ask-ind-sore-count,ask-pat-sore-grade1','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,1),
('ask-ind-sore-count','IN_IND',NULL,'IN','CARD','욕창 단계가 내려가거나 개수가 줄면 개선인가요?','욕창 단계·개수가 줄면 개선인가요','욕창개선판정 2단계 1단계 개수감소 단계하락 G3 G2 G1','네, 두 경우 모두 개선입니다.\n· <b>2단계 → 1단계</b>로 내려간 경우: 개선(1단계는 욕창 개선 대상 기준에서 제외되므로 2단계 이상에서 벗어나면 개선).\n· <b>개수 감소</b>: 예) 전월 G3 1개+G2 1개 → 당월 G3 1개+G1 1개 = 2단계 이상 욕창 개수가 줄어 <b>개선</b>입니다.\n반대로 전전월 2단계 → 전월 1단계 → 당월 치유 흐름이라면, 전월에 2단계 이상 욕창이 없으므로 당월은 개선 산정 대상 자체가 아닙니다.',NULL,'ask-ind-sore-denom,ask-pat-sore-hist','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,2),
('ask-ind-sorecare-denom','IN_IND',NULL,'IN','CARD','욕창이 힐링됐는데도 욕창처치 분모에 잡히는 이유는?','힐링됐는데 욕창처치 분모에 잡히는 이유','욕창처치 분모 힐링 전월욕창 처치실시 피부문제처치 4가지','욕창처치 실시 환자분율은 <b>전월 평가에서 1단계 이상 욕창이 있던 환자가 당월 분모</b>가 됩니다.\n따라서 당월에 힐링이 되었더라도 <b>당월 평가기간까지는 피부문제 처치를 실시하고 체크</b>해야 분자에 들어갑니다.\n피부문제 처치는 <b>압력을 줄여주는 도구 · 체위변경 · 영양공급 · 피부궤양 드레싱 4가지를 모두</b> 수행한 경우에 해당합니다. (걸어다니는 환자라도 욕창이 있으면 체위변경 등 처치 기준은 동일하게 적용됩니다.)',NULL,'ask-ind-sore-denom','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,3),
('ask-ind-foley-14d','IN_IND',NULL,'IN','CARD','유치도뇨관 14일 초과는 어느 날부터 세나요?','유치도뇨관 14일 초과는 언제부터 세나요','유치도뇨관 14일초과 15일 기산일 평가표작성일 다음날 폴리 타병원삽입','<b>당월(직전) 평가표 작성일 다음 날부터</b> 14일 초과 여부를 셉니다. 예) 6월 평가표를 6/10 작성 → 6/11부터 기산, 6/18 교환이면 이미 14일 초과가 아니라 <b>6/11~ 14일 이내 교체·제거</b>가 되어야 합니다.\n관리 구간은 <b>당월 평가표 작성일까지</b>입니다 — 작성일 이후의 유지·초과는 당월 지표와 무관하며, 다음 평가표 작성일 기준으로 다시 셉니다.\n<b>타병원에서 삽입하고 유지 상태로 입원</b>한 경우에도 집계에 포함되나, 본원 입원일부터 카운트되므로 삽입일자는 사실대로 기재하고 두셔도 됩니다.',NULL,'ask-ind-foley-check','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,4),
('ask-ind-foley-check','IN_IND',NULL,'IN','CARD','폴리 제거 후 ''조절 못함''으로 체크해도 되나요?','폴리 제거 후 조절 못함 체크 되나요','폴리제거 소변조절못함 유치도뇨관제거 기저귀 평가기간','네. <b>평가기간(관찰기간) 동안 폴리가 없는 상태</b>라면, 그 기간의 실제 배뇨 상태대로 ''조절 못함''을 체크하는 것이 맞습니다(오류가 아닙니다).\n반대로 폴리를 유지 중인 기간에는 소변조절 항목이 아니라 유치도뇨관 쪽에서 평가되므로, 간호기록에 제거 후에도 ''Foley keep'' 기록이 반복되지 않도록 정리가 필요합니다.',NULL,'ask-ind-foley-14d','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,5),
('ask-ind-bladder-jabo','IN_IND',NULL,'IN','CARD','자보(자동차보험) 환자도 배뇨관리 대상인가요?','자보 환자도 배뇨관리 대상인가요','자보 자동차보험 배뇨관리대상 부입원 부유형 평가표작성','아닙니다. <b>자보 환자는 배뇨관리 대상에 포함되지 않습니다.</b>\n자보가 주입원이고 건강보험은 부유형으로 행위 청구하는 경우에는 <b>환자평가표 자체를 작성하지 않습니다</b>.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,6),
('ask-ind-prev-notrain','IN_IND',NULL,'IN','CARD','이전 평가표를 적용한 달에도 배뇨훈련을 해야 하나요?','이전 평가표 적용 달에도 배뇨훈련 해야 하나요','이전평가표 이전적용 배뇨훈련 월말입원','아니요. 전월 말 입원 환자 등의 평가표를 당월에 <b>이전 적용</b>으로 사용하는 경우, 배뇨훈련 대상자여도 <b>당월에 배뇨훈련을 하지 않아도 됩니다</b>(당월 평가표를 새로 작성하지 않으므로).',NULL,'ask-pat-prev-apply,ask-pat-utrain-rec','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,7),
('ask-ind-adl-record','IN_IND',NULL,'IN','CARD','ADL 종합평가 간호기록은 언제 작성해야 하나요?','ADL 종합평가 기록은 언제 작성하나요','ADL종합평가 간호기록 작성시점 관찰기간 평가표작성일','평가표 작성일과 <b>일치하지 않아도 됩니다</b>. 통상 관찰기간을 충분히 본 뒤 <b>4~7일 사이에 작성</b>하며, 작성 시점 자체가 문제되지는 않습니다.\n신뢰도 점검에서는 <b>기록이 있는지 여부</b>를 확인하므로, 관찰기간 내에 ADL 관련 기록이 존재하도록 관리하는 것이 핵심입니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,8),
('ask-ind-result-when','IN_IND',NULL,'IN','CARD','적정성평가 결과 발표와 표준화구간 확인은 어디서 하나요?','적정성 결과 발표·표준화구간 확인은','결과발표 발표시기 수가연계 표준화구간 만점구간 2024 결과책자','결과 발표는 대략 <b>6월 20일 전후</b>로 이루어져 왔습니다(예: 2024년 평가 결과 → 2026년 6월경 발표). 등급 구간은 결과발표 책자에서 확인할 수 있습니다.\n지표별 <b>표준화(만점)구간</b>은 위체크 화면 상단의 <b>2024년도 표준화구간</b>에서 확인하실 수 있습니다. 배뇨관리(신설 지표)는 2024년 구간이 없어 예상 기준으로 관리합니다.','[{"n":"적정성평가 화면","u":"/main/assessment.do"}]',NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,9);
INSERT INTO TBL_QNA_KB (KB_CODE,CAT_ID,SUB_ID,SRC_TYPE,KIND,TITLE,SHORT_TITLE,KEYWORDS,BODY,GO_JSON,REL_IDS,SRC_NM,DOC_PAGE,WEIGHT,HIT_CNT,SORT_NO) VALUES
('ask-fee-kk054','IN_FEE',NULL,'IN','CARD','측관주사(KK054)와 KK020·KK053은 어떻게 구분하나요?','측관주사 KK054와 KK020 구분은','KK054 KK053 KK052 KK020 측관주사 사이드 믹스 정맥주사 수액','<b>KK054(측관 주입)</b>: 확보된 수액 통로(사이드)로 약제를 <b>직접 주입</b>하는 경우에만 산정합니다. 수액에 <b>믹스</b>해 달면 측관이 아니라 <b>KK053/KK052(수액제 주입)</b>로 산정합니다.\n<b>KK020(정맥내 일시 주사)</b>: 100mL 이상의 수액 주사가 없는 상태에서 정맥주사하는 경우 산정합니다.\n예) NS500 라인에 NS100+약제 믹스를 다는 경우 → KK053·KK052 / NS20+항생제를 헤파린캡으로 투여(다른 수액 없음) → 첫날 KK020+KK059(헤파린캡), 이후 KK020.',NULL,'ask-fee-iv-needle','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,3,1),
('ask-fee-iv-needle','IN_FEE',NULL,'IN','CARD','정맥내유지침·헤파린캡은 몇 개까지 청구되나요?','정맥내유지침은 몇 개까지 청구되나요','정맥내유지침 유치침 헤파린캡 헤파린콕 실사용량 개수 청구메모','정맥내유지침은 <b>실사용량으로 인정</b>됩니다. 양팔 2개 라인이면 2개, 주사 실패로 여러 개를 쓴 날도 <b>간호기록에 사용 내역을 작성</b>하면 인정됩니다. 사용량이 많은 날은 <b>청구메모</b>를 달아 청구하세요.\n헤파린캡(콕)은 통상 <b>3일에 1회 교체</b> 기준으로 교체 시마다 산정하고, 카테터 사용 내역을 기록에 남겨야 추후 현지조사에서 문제가 없습니다.',NULL,'ask-fee-kk054','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,2),
('ask-fee-bath','IN_FEE',NULL,'IN','CARD','침상목욕간호는 주 몇 회까지 산정하나요?','침상목욕간호는 주 몇 회 산정하나요','침상목욕 목욕간호 주1회 산정횟수','통상 <b>주 1회</b> 산정하고 있습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,3),
('ask-fee-slowrelease','IN_FEE',NULL,'IN','CARD','경관영양 환자에게 서방정을 갈아서 투여하면 삭감되나요?','서방정을 갈아서 투여하면 삭감되나요','서방정 서방형 분쇄 분할 경관영양 L-tube 삭감 크러쉬','네. <b>모든 경구용 서방형 제제는 분쇄(crush) 투여가 원칙적으로 불인정</b>이며, 경관영양 환자라도 동일하게 삭감됩니다.\n정제·캡슐의 분할(split) 투여는 <b>허가사항에 분할투여가 명시된 경우에만</b> 인정됩니다. 허가사항은 병원 약전(또는 식약처 허가정보)에서 확인하고, 처방 기초자료에 확인 안내가 뜨도록 세팅해 두는 것이 안전합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,4),
('ask-fee-isolation','IN_FEE',NULL,'IN','CARD','격리병실료는 어떤 경우에 산정할 수 있나요? (MRSA·옴)','격리병실료 산정 기준(MRSA·옴)은','격리병실료 격리실 MRSA 옴 가피성옴 다인실 2인실','<b>MRSA</b>: 격리병실 사용 기간만 산정 가능하며, 양성이라도 <b>일반 다인실로 이동하면 격리병실료 산정 불가</b>입니다(이후 평가표 작성·정액 적용).\n<b>옴</b>: 과거에는 장기 산정이 가능했으나 최근 심사 경향은 <b>24시간까지만</b> 인정하는 추세입니다(서울·경기지원 불인정 사례). <b>가피성 옴</b>은 의사가 감염력 소실로 판단할 때까지 인정될 수 있으나 <b>진단서를 첨부</b>해 청구하라는 안내를 받았습니다. 관련 간호기록·경과기록을 함께 남겨 두세요.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,5),
('ask-fee-antibiotic','IN_FEE',NULL,'IN','CARD','항생제는 왜 14일까지만 인정되나요?','항생제는 14일까지만 인정되나요','항생제 14일 삭감 폐렴 메펨 균배양 항생제교체','명문 규정이라기보다 <b>통용되는 심사 기준</b>입니다. 같은 항생제로 14일까지 치료해도 호전이 없으면 효과가 없다고 판단하므로, 이후에는 <b>원인균 배양·항생제 감수성 검사를 시행하고 항생제를 교체</b>하는 방향으로 의료진과 상의해야 합니다.\n(실제 1일 2회 21일 청구 → 1일 1회 14일만 인정된 사례가 있습니다.)',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,6),
('ask-fee-pneu-xray','IN_FEE',NULL,'IN','CARD','폐렴 특정기간은 언제부터 잡을 수 있나요? (X-ray 요건)','폐렴 특정기간은 언제부터 잡나요','폐렴 특정기간 엑스레이 X-ray 촬영일 hazziness infiltration 점검표','폐렴 시작일은 <b>X-ray 촬영일부터</b> 가능합니다. 증상과 항생제 투여만으로 그 전 날짜로 소급해 잡을 수는 없습니다(주말 등으로 촬영이 늦어도 촬영일 기준).\n판독 소견에 반드시 infiltration이 있어야 하는 것은 아니며, <b>음영(hazziness) 소견 + 담당의 폐렴 진단 + 폐렴 점검표</b>가 갖춰지면 가능합니다.',NULL,'ask-fee-sepsis-fever','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,7),
('ask-fee-sepsis-fever','IN_FEE',NULL,'IN','CARD','패혈증 점검표의 발열은 진단일 이전 것도 인정되나요?','패혈증 점검표 발열은 며칠 전까지 인정','패혈증 점검표 발열 열 진단일 3일','네. 모든 조건이 진단일 당일에 발현하는 것은 아니므로, 통상 <b>진단일 이전 3일까지의 발열</b>은 인정됩니다.\n예) 3/16 발열(38.1℃)로 해열제 투여, 3/17 패혈증 진단 → 점검표에 발열 체크 가능.',NULL,'ask-fee-pneu-xray','병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,8),
('ask-fee-upcoding','IN_FEE',NULL,'IN','CARD','의사 처방에 없는 상병을 청구명세서에 넣으면 어떤 문제가 되나요?','처방에 없는 상병을 명세서에 넣으면','업코딩 상병 청구명세서 진단명 임의기재 삭감방지','의사가 진단하지 않은 상병을 청구자가 임의로 기재하는 것은 <b>업코딩</b>에 해당합니다. 청구명세서의 상병은 환자가 진단받은 상병인데, 심사자(청구자)가 진단을 내린 셈이 되기 때문입니다.\n삭감 방지 목적이라도 위험하므로, <b>원장님이 점검표·처방 작성 시 진단명을 함께 기재</b>하도록 협의하는 것이 올바른 방향입니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,9),
('ask-fee-dur','IN_FEE',NULL,'IN','CARD','DUR 점검을 누락했거나 의사가 퇴사한 경우 어떻게 하나요?','DUR 누락·의사 퇴사 시 처리 방법','DUR 점검누락 재점검 7일 퇴사의사 리피트 처방의사','점검이 누락된 경우 <b>7일 이내 재점검 후 송신</b>하면 되고, <b>약 투여가 종료되기 전</b>에 진행해야 합니다.\n의사 퇴사 후 새 의사가 기존 오더를 리피트하는 경우 DUR이 기존(퇴사) 의사 이름으로 전송되는데, 정석은 퇴사일자로 끊어 새 의사 오더를 내는 것이지만, 이런 사례가 병원마다 빈번해 <b>현지조사에서 지적된 사례는 확인되지 않았습니다</b>.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,10),
('ask-fee-jabo-dementia','IN_FEE',NULL,'IN','CARD','자보 선택입원군 환자에게 치매약을 시작하면 환자군이 바뀌나요?','자보 환자 치매약 시작 시 환자군은','자보 선택입원군 치매약 문제행동군 건보 약제청구','아니요. <b>자보는 선택입원군을 유지</b>하고, <b>건강보험으로 치매약만 별도 청구</b>합니다. 치매 진단·투약을 이유로 자보 입원을 중도 환자군으로 바꾸지 않습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,11),
('ask-fee-dietmgr','IN_FEE',NULL,'IN','CARD','치료식 영양관리료의 1일 40명 제한에 의료급여 환자도 포함되나요?','치료식영양관리료 40명에 보호환자 포함?','치료식영양관리료 영양사 40명 보호환자 의료급여','영양사 1인당 1일 40명 제한은 <b>건강보험 환자 기준</b>입니다. 의료급여(보호) 환자는 인원 수 제한과 무관하며, 산정하지 않아도 됩니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,12),
('ask-fee-fullself','IN_FEE',NULL,'IN','CARD','정액수가 환자에게 전액본인부담·비급여로 받을 수 있나요?','정액환자 전액본인부담·비급여 수납 가능?','정액수가 전액본인부담 100대100 비급여 급여약 영양제','요양병원 <b>정액수가 환자는 원칙상 전액본인부담(100/100)도 별도 수납할 수 없습니다</b>. 급여 기준을 벗어난 급여약(예: 영양주사)을 전액본인부담으로 돌려 받는 것도 마찬가지입니다.\n<b>급여로 등재된 약을 비급여로 수납하는 것도 불가</b>합니다 — 비급여 수납은 비급여로 등재된 항목만 가능합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,13),
('ask-fee-outmed','IN_FEE',NULL,'IN','CARD','보호자가 외진 약(원외 처방약)을 부담하겠다는데 청구를 안 해도 되나요?','외진 약을 보호자가 부담하면 청구 생략?','외진 원외약 보호자부담 확인서 입원료약제포함 퇴원입원처리','요양병원 입원료(정액)에는 약제비가 포함되어 있어 추후 문제 소지가 있습니다. 부득이 보호자가 부담하는 경우에는 <b>해당 부분을 청구하지 않겠다는 확인서</b>를 받아 두는 것이 안전합니다(퇴원 후 문제 삼는 사례가 있었습니다).\n위험을 가장 줄이는 방법은 외진 기간을 <b>퇴원 후 재입원으로 처리</b>하는 것입니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,14),
('ask-fee-airmat','IN_FEE',NULL,'IN','CARD','에어매트리스 비용을 보호자에게 받아도 되나요?','에어매트리스 비용 보호자 수납 가능?','에어매트리스 욕창매트 보호자수납 현지조사 판매업','받지 않는 것이 안전합니다. 최근 현지조사에서 문제가 된 병원이 있습니다.\n원내 매점(별도 사업자)을 통한 판매라면 가능할 수 있으나, 요양병원은 의료기관(보건업)이라 <b>병원이 직접 판매·수납하는 것은 불가</b>하다는 판단이었습니다. 조사자에 따라 점검 여부가 다르니 관리해 두시는 것이 좋습니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,15),
('ask-fee-sore-mat','IN_FEE',NULL,'IN','CARD','욕창 치료재료(거즈·폼드레싱)를 EMR에 입력하지 않으면 문제되나요?','욕창 치료재료 미입력이 문제되나요','욕창치료재료 거즈 메디폼 염증성처치 단순처치 현지조사 개수산정','일반 거즈 등은 <b>단순처치·염증성처치 수가에 이미 포함</b>되어 있어 별도 입력 없이 사용해도 됩니다. 현지조사·신뢰도점검은 <b>의무기록과 욕창 사진</b>을 근거로 하며, 어떤 재료로 치유했는지를 조사하지는 않습니다.\n<b>염증성 처치 개수 산정</b>: 욕창 개수만큼 처방이 필요하며, 양쪽 엉덩이는 양쪽 하지로 보아 <b>2개</b>, coccyx(꼬리뼈) 부위는 <b>1개</b>로 산정합니다.',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,2,16),
('ask-fee-actdesc','IN_FEE',NULL,'IN','CARD','행위기술서(행위 정의)는 어디서 검색하나요?','행위기술서는 어디서 검색하나요','행위기술서 심사기준종합서비스 행위정의 수가검색 방광천자','심사평가원 <b>심사기준종합서비스 → 행위 → 행위기술서</b>에서 행위명으로 검색하면 기술서를 확인할 수 있습니다.\n예) 방광천자 등 생소한 처치의 산정 가능 여부·정의를 확인할 때 유용합니다. (참고: 소변이 탁하거나 안 나올 때 통상 시행하는 수가는 R3490 방광 및 요도세척입니다.)',NULL,NULL,'병원 실무 카톡 질의응답 정리(2026-08-05) — 위너넷 컨설팅 답변',0,20,1,17);
